# Read originals directly, using published OOXML, without editing the workbooks.
import zipfile,xml.etree.ElementTree as E
qdata={};ns={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
for fn in ['microsoft-questionnaire.xlsx','sap-questionnaire.xlsx']:
 with zipfile.ZipFile(ROOT/'sources/client'/fn) as z:
  strings=[''.join(t.itertext()) for t in E.fromstring(z.read('xl/sharedStrings.xml')).findall('s:si',ns)]
  rel={x.attrib['Id']:x.attrib['Target'] for x in E.fromstring(z.read('xl/_rels/workbook.xml.rels'))}
  sheet=next(s for s in E.fromstring(z.read('xl/workbook.xml')).findall('s:sheets/s:sheet',ns) if s.attrib['name']=='1. Besoins fonctionnels ')
  target=rel[sheet.attrib['{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id']]
  target=target.lstrip('/') if target.startswith('/') else 'xl/'+target
  rows=[]
  for row in E.fromstring(z.read(target)).findall('s:sheetData/s:row',ns):
   cells={}
   for c in row.findall('s:c',ns):
    v=c.find('s:v',ns);v=v.text if v is not None else ''.join(c.find('s:is',ns).itertext()) if c.find('s:is',ns) is not None else ''
    if c.attrib.get('t')=='s':v=strings[int(v)]
    if v.strip():cells[c.attrib['r']]=v
   if cells:rows.append(cells)
  qdata[fn]={'1. Besoins fonctionnels ':rows}
